reg llm_go_signal = 1;


reg clk,rst;
reg IN;
wire MATCH;

fsm DUT(.CLK(clk),.RST(rst),.IN(IN),.MATCH(MATCH));

initial begin
	clk=0;
	forever #5 clk=~clk;
end

integer error = 0;
initial begin
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

	#10;
	rst =1;
	#28;
	rst = 0;
	IN = 0;
	#10 IN=0;
        // $display("%b, %b", MATCH, DUT.ST_cr);//0
        error = (MATCH==0)? error:error+1;
        #10 IN=0;
        // $display("%b, %b", MATCH, DUT.ST_cr);//00
        error = (MATCH==0)? error:error+1;
        #10 IN=1;
        // $display("%b, %b", MATCH, DUT.ST_cr);//001
        error = (MATCH==0)? error:error+1;
        #10 IN=1;  
        // $display("%b, %b", MATCH, DUT.ST_cr);//0011
        error = (MATCH==0)? error:error+1;
        #10 IN=0;
        // $display("%b, %b", MATCH, DUT.ST_cr);//00110
        error = (MATCH==0)? error:error+1;
        #10 IN=0;
        // $display("%b, %b", MATCH, DUT.ST_cr);//001100
        error = (MATCH==0)? error:error+1;
        #10 IN=1;
        // $display("%b, %b", MATCH, DUT.ST_cr);//0011001
        error = (MATCH==0)? error:error+1;
        #10 IN=1;
        // $display("%b, %b", MATCH, DUT.ST_cr);//00110011
        error = (MATCH==1)? error:error+1;
        #10 IN=0;
        // $display("%b, %b", MATCH, DUT.ST_cr);//001100110
        error = (MATCH==0)? error:error+1;
        #10 IN=0;
        // $display("%b, %b", MATCH, DUT.ST_cr);//0011001100
        error = (MATCH==0)? error:error+1;
        #10 IN=1;
        // $display("%b, %b", MATCH, DUT.ST_cr);//00110011001
        error = (MATCH==0)? error:error+1;
        #10 IN=1;
        // $display("%b, %b", MATCH, DUT.ST_cr);//001100110011
        error = (MATCH==1)? error:error+1;
        if(error==0)begin
                $display("===========Your Design Passed===========");
        end
        else begin
                $display("===========Error===========");
        end
	$finish;
end




        ///////////////////added
        integer file_mantra;
        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      $fwrite(file_mantra, "MATCH,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        $fwrite(file_mantra, "%h, ", MATCH);

            $fwrite(file_mantra, "\n");
          end
        end





// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST


    // 2. THEN WAIT for original tests
    // Ensures synchronization with the test harness
    wait(llm_go_signal == 1);

    // 3. THEN execute logic
    $display("LLM: Starting Mutation Tests...");

    // Initialize Inputs
    rst = 1;
    IN = 0;
    #20;

    // Release Reset
    rst = 0;
    #10;

    // --- Targeted State Transitions to Kill Mutations ---
    // The original testbench misses several transitions (s2->s1, s3->s0, s4->s2, s5->s1).
    // We explicitly target these to expose state transition faults.

    // Path 1: s0 -> s1 -> s2 -> s1 (Loop back)
    // Current State: s0
    IN = 1; #10; // Transition to s1
    IN = 0; #10; // Transition to s2
    IN = 1; #10; // Transition to s1 (Targeting unused transition s2->s1)

    // Path 2: s1 -> s2 -> s3 -> s0 (Loop back)
    // Current State: s1
    IN = 0; #10; // Transition to s2
    IN = 0; #10; // Transition to s3
    IN = 0; #10; // Transition to s0 (Targeting unused transition s3->s0)

    // Path 3: s0 -> s1 -> s2 -> s3 -> s4 -> s2 (Drop from Match state)
    // Current State: s0
    IN = 1; #10; // Transition to s1
    IN = 0; #10; // Transition to s2
    IN = 0; #10; // Transition to s3
    IN = 1; #10; // Transition to s4
    // In s4, IN=0. MATCH should be 0. Next state s2.
    IN = 0; #10; // Transition to s2 (Targeting unused transition s4->s2)

    // Path 4: s2 -> s3 -> s4 -> s5 -> s1 (Loop from s5)
    // Current State: s2
    IN = 0; #10; // Transition to s3
    IN = 1; #10; // Transition to s4
    // In s4, IN=1. MATCH should be 1. Next state s5.
    IN = 1; #10; // Transition to s5
    // In s5, IN=1. Next state s1.
    IN = 1; #10; // Transition to s1 (Targeting unused transition s5->s1)

    // Path 5: s1 -> s2 -> s3 -> s4 -> s5 -> s2 (Standard drop from s5)
    // Current State: s1
    IN = 0; #10; // Transition to s2
    IN = 0; #10; // Transition to s3
    IN = 1; #10; // Transition to s4
    IN = 1; #10; // Transition to s5
    IN = 0; #10; // Transition to s2

    // --- Async Reset Test ---
    // Assert Reset in middle of operation (State s2) to test sensitivity list mutations
    #5; 
    rst = 1;
    #10;
    rst = 0;
    IN = 0;
    #10;

    // --- Glitch / Timing Test ---
    // Rapid changes to test non-blocking/blocking mutations and setup/hold violations
    IN = 1; #2;
    IN = 0; #2;
    IN = 1; #2;
    IN = 0; #4;

    // Stabilize before handover
    IN = 0;
    #20;

    // 4. Handover
    $display("LLM: Tests Complete. Handing over.");
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (file_mantra != 0) $fclose(file_mantra);
    $finish;
end

endmodule

